solution:
function spareSets(parts: number[]): number[][] {
  const out: number[][] = [];
  const cur: number[] = [];
  const go = (i: number) => {
    if (i === parts.length) { out.push([...cur]); return; }
    go(i + 1);
    cur.push(parts[i]);
    go(i + 1);
    cur.pop();
  };
  go(0);
  return out;
}
